use std::env;
use std::fs;
use std::io::Write;
use std::path::{Path, PathBuf};
use std::process::ExitCode;
use std::time::{SystemTime, UNIX_EPOCH};

mod cli;
mod commands;
mod error_log;
mod languages;
mod tui;
mod time_util;

use cli::{Cli, CliAction};

fn main() -> ExitCode {
    let argv: Vec<String> = env::args().collect();
    let bin_name = argv.first()
        .map(|s| Path::new(s).file_name().and_then(|n| n.to_str()).unwrap_or(s).to_string())
        .unwrap_or_else(|| "gittype".to_string());

    let args: Vec<String> = argv.iter().skip(1).cloned().collect();

    let parsed = cli::parse(&bin_name, &args);

    match parsed {
        CliAction::Help { long, ctx } => {
            print!("{}", cli::render_help(&bin_name, &ctx, long));
            ExitCode::from(0)
        }
        CliAction::Version => {
            println!("gittype 0.8.0");
            ExitCode::from(0)
        }
        CliAction::Error { message, ctx } => {
            eprint!("{}", cli::render_error(&bin_name, &message, &ctx));
            ExitCode::from(2)
        }
        CliAction::Run(cli) => run(cli, &argv),
    }
}

fn run(cli: Cli, argv: &[String]) -> ExitCode {
    match cli {
        Cli::Game { repo_path, repo, langs } => {
            // Validate langs first
            if let Some(l) = langs.as_deref() {
                if let Err(msg) = languages::validate_langs(l) {
                    eprint!("{}", msg);
                    return ExitCode::from(1);
                }
            }
            // Then try to start terminal which will fail
            match tui::launch_tui() {
                Ok(()) => ExitCode::from(0),
                Err(e) => {
                    let _ = repo_path; let _ = repo;
                    error_log::report_error(&e, argv);
                    ExitCode::from(1)
                }
            }
        }
        Cli::History => {
            eprintln!("❌ History command is not yet implemented");
            eprintln!("💡 This feature is planned for a future release");
            ExitCode::from(0)
        }
        Cli::Stats => {
            eprintln!("❌ Stats command is not yet implemented");
            eprintln!("💡 This feature is planned for a future release");
            ExitCode::from(0)
        }
        Cli::Export { format, output } => {
            eprintln!("❌ Export command is not yet implemented");
            eprintln!("💡 Requested format: {}", format);
            if let Some(out) = output {
                eprintln!("💡 Requested output: {}", out);
            }
            eprintln!("💡 This feature is planned for a future release");
            ExitCode::from(0)
        }
        Cli::CacheStats => {
            commands::cache::stats();
            ExitCode::from(0)
        }
        Cli::CacheClear => {
            commands::cache::clear();
            ExitCode::from(0)
        }
        Cli::CacheList => {
            commands::cache::list();
            ExitCode::from(0)
        }
        Cli::RepoList => {
            commands::repo::list(argv);
            ExitCode::from(0)
        }
        Cli::RepoClear => {
            commands::repo::clear();
            ExitCode::from(0)
        }
        Cli::RepoPlay => {
            match tui::launch_tui() {
                Ok(()) => ExitCode::from(0),
                Err(e) => {
                    error_log::report_error(&e, argv);
                    ExitCode::from(1)
                }
            }
        }
        Cli::Trending { language, repo_name, period } => {
            let _ = period; let _ = repo_name;
            // Validate language
            if let Some(ref lang) = language {
                if !languages::is_trending_language(lang) {
                    eprintln!("❌ Unsupported language: '{}'", lang);
                    eprintln!("📚 Supported languages: {}", languages::TRENDING_LANGUAGES.join(", "));
                    let err = format!("Validation error: Unsupported language: {}", lang);
                    error_log::report_validation_error(&err, argv);
                    return ExitCode::from(1);
                }
            }
            match tui::launch_tui() {
                Ok(()) => ExitCode::from(0),
                Err(e) => {
                    error_log::report_error(&e, argv);
                    ExitCode::from(1)
                }
            }
        }
    }
}
