// A custom CLI parser that mimics the clap v4 output format used by the original
// gittype binary. Covers only the subset we need: subcommand dispatch,
// short/long help, version, and a handful of specific error formats.

#[derive(Debug, Clone)]
pub enum Cli {
    Game {
        repo_path: Option<String>,
        repo: Option<String>,
        langs: Option<String>,
    },
    History,
    Stats,
    Export {
        format: String,
        output: Option<String>,
    },
    CacheStats,
    CacheClear,
    CacheList,
    RepoList,
    RepoClear,
    RepoPlay,
    Trending {
        language: Option<String>,
        repo_name: Option<String>,
        period: String,
    },
}

#[derive(Debug, Clone)]
pub enum HelpCtx {
    Root,
    History,
    Stats,
    Export,
    Cache,
    CacheStats,
    CacheClear,
    CacheList,
    CacheHelp,
    Repo,
    RepoList,
    RepoClear,
    RepoPlay,
    RepoHelp,
    Trending,
    Help,
}

impl HelpCtx {
    pub fn usage_line(&self, bin: &str) -> String {
        match self {
            HelpCtx::Root => format!("Usage: {} [OPTIONS] [REPO_PATH] [COMMAND]", bin),
            HelpCtx::History => format!("Usage: {} history", bin),
            HelpCtx::Stats => format!("Usage: {} stats", bin),
            HelpCtx::Export => format!("Usage: {} export [OPTIONS]", bin),
            HelpCtx::Cache => format!("Usage: {} cache <COMMAND>", bin),
            HelpCtx::CacheStats => format!("Usage: {} cache stats", bin),
            HelpCtx::CacheClear => format!("Usage: {} cache clear", bin),
            HelpCtx::CacheList => format!("Usage: {} cache list", bin),
            HelpCtx::CacheHelp => format!("Usage: {} cache help [COMMAND]...", bin),
            HelpCtx::Repo => format!("Usage: {} repo <COMMAND>", bin),
            HelpCtx::RepoList => format!("Usage: {} repo list", bin),
            HelpCtx::RepoClear => format!("Usage: {} repo clear", bin),
            HelpCtx::RepoPlay => format!("Usage: {} repo play", bin),
            HelpCtx::RepoHelp => format!("Usage: {} repo help [COMMAND]...", bin),
            HelpCtx::Trending => format!("Usage: {} trending [OPTIONS] [LANGUAGE] [REPO_NAME]", bin),
            HelpCtx::Help => format!("Usage: {} help [COMMAND]...", bin),
        }
    }
}

pub enum CliAction {
    Run(Cli),
    Help { long: bool, ctx: HelpCtx },
    Version,
    Error { message: String, ctx: HelpCtx },
}

pub fn parse(bin: &str, args: &[String]) -> CliAction {
    let _ = bin;
    parse_root(args)
}

fn parse_root(args: &[String]) -> CliAction {
    let mut i = 0;
    let mut repo_path: Option<String> = None;
    let mut repo: Option<String> = None;
    let mut langs: Option<String> = None;
    let mut double_dash = false;

    while i < args.len() {
        let a = &args[i];
        if !double_dash {
            if a == "--" {
                double_dash = true;
                i += 1;
                continue;
            }
            if a == "--help" {
                return CliAction::Help { long: true, ctx: HelpCtx::Root };
            }
            if a == "-h" {
                return CliAction::Help { long: false, ctx: HelpCtx::Root };
            }
            if a == "--version" || a == "-V" {
                return CliAction::Version;
            }
            if a == "--repo" {
                i += 1;
                if i >= args.len() {
                    return CliAction::Error {
                        message: "a value is required for '--repo <REPO>' but none was supplied".to_string(),
                        ctx: HelpCtx::Root,
                    };
                }
                repo = Some(args[i].clone());
                i += 1;
                continue;
            }
            if let Some(v) = a.strip_prefix("--repo=") {
                repo = Some(v.to_string());
                i += 1;
                continue;
            }
            if a == "--langs" {
                i += 1;
                if i >= args.len() {
                    return CliAction::Error {
                        message: "a value is required for '--langs <LANGS>' but none was supplied".to_string(),
                        ctx: HelpCtx::Root,
                    };
                }
                langs = Some(args[i].clone());
                i += 1;
                continue;
            }
            if let Some(v) = a.strip_prefix("--langs=") {
                langs = Some(v.to_string());
                i += 1;
                continue;
            }
            if a.starts_with('-') && a != "-" {
                return CliAction::Error {
                    message: format!("unexpected argument '{}' found\n\n  tip: to pass '{}' as a value, use '-- {}'", a, a, a),
                    ctx: HelpCtx::Root,
                };
            }
            // Check subcommand
            if repo_path.is_none() {
                match a.as_str() {
                    "history" => return parse_history(&args[i + 1..]),
                    "stats" => return parse_stats(&args[i + 1..]),
                    "export" => return parse_export(&args[i + 1..]),
                    "cache" => return parse_cache(&args[i + 1..]),
                    "repo" => return parse_repo(&args[i + 1..]),
                    "trending" => return parse_trending(&args[i + 1..]),
                    "help" => return parse_help(&args[i + 1..], HelpCtx::Root),
                    _ => {
                        repo_path = Some(a.clone());
                        i += 1;
                        continue;
                    }
                }
            }
            // Extra positional
            return CliAction::Error {
                message: format!("unexpected argument '{}' found", a),
                ctx: HelpCtx::Root,
            };
        } else {
            // After --
            if repo_path.is_none() {
                repo_path = Some(a.clone());
                i += 1;
                continue;
            }
            return CliAction::Error {
                message: format!("unexpected argument '{}' found", a),
                ctx: HelpCtx::Root,
            };
        }
    }

    CliAction::Run(Cli::Game { repo_path, repo, langs })
}

fn parse_history(args: &[String]) -> CliAction {
    match parse_simple_flags(args, HelpCtx::History) {
        SimpleRes::Ok => CliAction::Run(Cli::History),
        SimpleRes::Help(long) => CliAction::Help { long, ctx: HelpCtx::History },
        SimpleRes::Err(e) => CliAction::Error { message: e, ctx: HelpCtx::History },
    }
}

fn parse_stats(args: &[String]) -> CliAction {
    match parse_simple_flags(args, HelpCtx::Stats) {
        SimpleRes::Ok => CliAction::Run(Cli::Stats),
        SimpleRes::Help(long) => CliAction::Help { long, ctx: HelpCtx::Stats },
        SimpleRes::Err(e) => CliAction::Error { message: e, ctx: HelpCtx::Stats },
    }
}

enum SimpleRes {
    Ok,
    Help(bool),
    Err(String),
}

fn parse_simple_flags(args: &[String], _ctx: HelpCtx) -> SimpleRes {
    for a in args {
        match a.as_str() {
            "--help" => return SimpleRes::Help(true),
            "-h" => return SimpleRes::Help(false),
            _ => {
                return SimpleRes::Err(format!("unexpected argument '{}' found", a));
            }
        }
    }
    SimpleRes::Ok
}

fn parse_export(args: &[String]) -> CliAction {
    let mut format = "json".to_string();
    let mut output: Option<String> = None;
    let mut i = 0;
    while i < args.len() {
        let a = &args[i];
        match a.as_str() {
            "--help" => return CliAction::Help { long: true, ctx: HelpCtx::Export },
            "-h" => return CliAction::Help { long: false, ctx: HelpCtx::Export },
            "--format" => {
                i += 1;
                if i >= args.len() {
                    return CliAction::Error {
                        message: "a value is required for '--format <FORMAT>' but none was supplied".to_string(),
                        ctx: HelpCtx::Export,
                    };
                }
                format = args[i].clone();
                i += 1;
            }
            "--output" => {
                i += 1;
                if i >= args.len() {
                    return CliAction::Error {
                        message: "a value is required for '--output <OUTPUT>' but none was supplied".to_string(),
                        ctx: HelpCtx::Export,
                    };
                }
                output = Some(args[i].clone());
                i += 1;
            }
            _ => {
                if let Some(v) = a.strip_prefix("--format=") {
                    format = v.to_string();
                    i += 1;
                } else if let Some(v) = a.strip_prefix("--output=") {
                    output = Some(v.to_string());
                    i += 1;
                } else {
                    return CliAction::Error {
                        message: format!("unexpected argument '{}' found", a),
                        ctx: HelpCtx::Export,
                    };
                }
            }
        }
    }
    CliAction::Run(Cli::Export { format, output })
}

fn parse_cache(args: &[String]) -> CliAction {
    if args.is_empty() {
        // In clap, missing subcommand prints help with exit code 2.
        return CliAction::Error {
            message: String::new(), // signal: just print help as "error"
            ctx: HelpCtx::Cache,
        };
    }
    let first = &args[0];
    match first.as_str() {
        "--help" => CliAction::Help { long: true, ctx: HelpCtx::Cache },
        "-h" => CliAction::Help { long: false, ctx: HelpCtx::Cache },
        "stats" => match parse_simple_flags(&args[1..], HelpCtx::CacheStats) {
            SimpleRes::Ok => CliAction::Run(Cli::CacheStats),
            SimpleRes::Help(long) => CliAction::Help { long, ctx: HelpCtx::CacheStats },
            SimpleRes::Err(e) => CliAction::Error { message: e, ctx: HelpCtx::CacheStats },
        },
        "clear" => match parse_simple_flags(&args[1..], HelpCtx::CacheClear) {
            SimpleRes::Ok => CliAction::Run(Cli::CacheClear),
            SimpleRes::Help(long) => CliAction::Help { long, ctx: HelpCtx::CacheClear },
            SimpleRes::Err(e) => CliAction::Error { message: e, ctx: HelpCtx::CacheClear },
        },
        "list" => match parse_simple_flags(&args[1..], HelpCtx::CacheList) {
            SimpleRes::Ok => CliAction::Run(Cli::CacheList),
            SimpleRes::Help(long) => CliAction::Help { long, ctx: HelpCtx::CacheList },
            SimpleRes::Err(e) => CliAction::Error { message: e, ctx: HelpCtx::CacheList },
        },
        "help" => parse_help_cache(&args[1..]),
        other => CliAction::Error {
            message: format!("unrecognized subcommand '{}'", other),
            ctx: HelpCtx::Cache,
        },
    }
}

fn parse_repo(args: &[String]) -> CliAction {
    if args.is_empty() {
        return CliAction::Error {
            message: String::new(),
            ctx: HelpCtx::Repo,
        };
    }
    let first = &args[0];
    match first.as_str() {
        "--help" => CliAction::Help { long: true, ctx: HelpCtx::Repo },
        "-h" => CliAction::Help { long: false, ctx: HelpCtx::Repo },
        "list" => match parse_simple_flags(&args[1..], HelpCtx::RepoList) {
            SimpleRes::Ok => CliAction::Run(Cli::RepoList),
            SimpleRes::Help(long) => CliAction::Help { long, ctx: HelpCtx::RepoList },
            SimpleRes::Err(e) => CliAction::Error { message: e, ctx: HelpCtx::RepoList },
        },
        "clear" => match parse_simple_flags(&args[1..], HelpCtx::RepoClear) {
            SimpleRes::Ok => CliAction::Run(Cli::RepoClear),
            SimpleRes::Help(long) => CliAction::Help { long, ctx: HelpCtx::RepoClear },
            SimpleRes::Err(e) => CliAction::Error { message: e, ctx: HelpCtx::RepoClear },
        },
        "play" => match parse_simple_flags(&args[1..], HelpCtx::RepoPlay) {
            SimpleRes::Ok => CliAction::Run(Cli::RepoPlay),
            SimpleRes::Help(long) => CliAction::Help { long, ctx: HelpCtx::RepoPlay },
            SimpleRes::Err(e) => CliAction::Error { message: e, ctx: HelpCtx::RepoPlay },
        },
        "help" => parse_help_repo(&args[1..]),
        other => CliAction::Error {
            message: format!("unrecognized subcommand '{}'", other),
            ctx: HelpCtx::Repo,
        },
    }
}

fn parse_trending(args: &[String]) -> CliAction {
    let mut period = "daily".to_string();
    let mut language: Option<String> = None;
    let mut repo_name: Option<String> = None;
    let mut i = 0;
    while i < args.len() {
        let a = &args[i];
        match a.as_str() {
            "--help" => return CliAction::Help { long: true, ctx: HelpCtx::Trending },
            "-h" => return CliAction::Help { long: false, ctx: HelpCtx::Trending },
            "--period" => {
                i += 1;
                if i >= args.len() {
                    return CliAction::Error {
                        message: "a value is required for '--period <PERIOD>' but none was supplied".to_string(),
                        ctx: HelpCtx::Trending,
                    };
                }
                period = args[i].clone();
                i += 1;
            }
            _ => {
                if let Some(v) = a.strip_prefix("--period=") {
                    period = v.to_string();
                    i += 1;
                } else if a.starts_with("--") {
                    return CliAction::Error {
                        message: format!("unexpected argument '{}' found", a),
                        ctx: HelpCtx::Trending,
                    };
                } else if language.is_none() {
                    language = Some(a.clone());
                    i += 1;
                } else if repo_name.is_none() {
                    repo_name = Some(a.clone());
                    i += 1;
                } else {
                    return CliAction::Error {
                        message: format!("unexpected argument '{}' found", a),
                        ctx: HelpCtx::Trending,
                    };
                }
            }
        }
    }
    CliAction::Run(Cli::Trending { language, repo_name, period })
}

fn parse_help(args: &[String], base_ctx: HelpCtx) -> CliAction {
    // `help [COMMAND]...` - treat as printing long help for the resolved subcommand
    if args.is_empty() {
        return CliAction::Help { long: true, ctx: base_ctx };
    }
    if args[0] == "--help" || args[0] == "-h" {
        return CliAction::Help { long: true, ctx: HelpCtx::Help };
    }
    resolve_help_chain(&args.iter().map(|s| s.as_str()).collect::<Vec<_>>(), base_ctx)
}

fn parse_help_cache(args: &[String]) -> CliAction {
    if args.is_empty() {
        return CliAction::Help { long: true, ctx: HelpCtx::Cache };
    }
    if args[0] == "--help" || args[0] == "-h" {
        return CliAction::Help { long: true, ctx: HelpCtx::CacheHelp };
    }
    resolve_help_chain_cache(&args.iter().map(|s| s.as_str()).collect::<Vec<_>>())
}

fn parse_help_repo(args: &[String]) -> CliAction {
    if args.is_empty() {
        return CliAction::Help { long: true, ctx: HelpCtx::Repo };
    }
    if args[0] == "--help" || args[0] == "-h" {
        return CliAction::Help { long: true, ctx: HelpCtx::RepoHelp };
    }
    resolve_help_chain_repo(&args.iter().map(|s| s.as_str()).collect::<Vec<_>>())
}

fn resolve_help_chain(args: &[&str], root: HelpCtx) -> CliAction {
    // If called on top-level: support `help <sub>` with optional further subs
    // Accept chains like: help cache, help cache stats, help trending, help history, help help
    match args[0] {
        "history" => CliAction::Help { long: true, ctx: HelpCtx::History },
        "stats" => CliAction::Help { long: true, ctx: HelpCtx::Stats },
        "export" => CliAction::Help { long: true, ctx: HelpCtx::Export },
        "trending" => CliAction::Help { long: true, ctx: HelpCtx::Trending },
        "help" => CliAction::Help { long: true, ctx: HelpCtx::Help },
        "cache" => {
            if args.len() == 1 {
                CliAction::Help { long: true, ctx: HelpCtx::Cache }
            } else {
                resolve_help_chain_cache(&args[1..])
            }
        }
        "repo" => {
            if args.len() == 1 {
                CliAction::Help { long: true, ctx: HelpCtx::Repo }
            } else {
                resolve_help_chain_repo(&args[1..])
            }
        }
        other => CliAction::Error {
            message: format!("unrecognized subcommand '{}'", other),
            ctx: root,
        },
    }
}

fn resolve_help_chain_cache(args: &[&str]) -> CliAction {
    match args[0] {
        "stats" => CliAction::Help { long: true, ctx: HelpCtx::CacheStats },
        "clear" => CliAction::Help { long: true, ctx: HelpCtx::CacheClear },
        "list" => CliAction::Help { long: true, ctx: HelpCtx::CacheList },
        "help" => CliAction::Help { long: true, ctx: HelpCtx::CacheHelp },
        other => CliAction::Error {
            message: format!("unrecognized subcommand '{}'", other),
            ctx: HelpCtx::Cache,
        },
    }
}

fn resolve_help_chain_repo(args: &[&str]) -> CliAction {
    match args[0] {
        "list" => CliAction::Help { long: true, ctx: HelpCtx::RepoList },
        "clear" => CliAction::Help { long: true, ctx: HelpCtx::RepoClear },
        "play" => CliAction::Help { long: true, ctx: HelpCtx::RepoPlay },
        "help" => CliAction::Help { long: true, ctx: HelpCtx::RepoHelp },
        other => CliAction::Error {
            message: format!("unrecognized subcommand '{}'", other),
            ctx: HelpCtx::Repo,
        },
    }
}

pub fn render_error(bin: &str, msg: &str, ctx: &HelpCtx) -> String {
    if msg.is_empty() {
        // Missing subcommand: print help (on stdout?) No - cache with no args prints to stdout.
        // Keep empty to trigger behavior in caller.
        return render_help(bin, ctx, false);
    }
    format!(
        "error: {}\n\n{}\n\nFor more information, try '--help'.\n",
        msg,
        ctx.usage_line(bin)
    )
}

pub fn render_help(bin: &str, ctx: &HelpCtx, long: bool) -> String {
    match ctx {
        HelpCtx::Root => render_root_help(bin, long),
        HelpCtx::History => render_simple_help(bin, "Show session history", ctx),
        HelpCtx::Stats => render_simple_help(bin, "Show analytics", ctx),
        HelpCtx::Export => render_export_help(bin),
        HelpCtx::Cache => render_cache_help(bin),
        HelpCtx::CacheStats => render_simple_help(bin, "Show cache statistics", ctx),
        HelpCtx::CacheClear => render_simple_help(bin, "Clear all cached challenges", ctx),
        HelpCtx::CacheList => render_simple_help(bin, "List cached repository keys", ctx),
        HelpCtx::CacheHelp => render_subhelp_help(bin, &HelpCtx::CacheHelp),
        HelpCtx::Repo => render_repo_help(bin),
        HelpCtx::RepoList => render_simple_help(bin, "List all cached repositories", ctx),
