use std::path::PathBuf;

fn cache_dir() -> PathBuf {
    if let Some(home) = std::env::var_os("HOME") {
        let mut p = PathBuf::from(home);
        p.push(".gittype");
        p.push("cache");
        p
    } else {
        PathBuf::from(".gittype-cache")
    }
}

pub fn stats() {
