    if dir.exists() {
        let _ = std::fs::remove_dir_all(&dir);
    }
    println!("Challenge cache cleared successfully.");
}

pub fn list() {
    let dir = cache_dir();
    if !dir.exists() {
        println!("No cached challenges found.");
        return;
    }
    let mut entries: Vec<String> = Vec::new();
    if let Ok(rd) = std::fs::read_dir(&dir) {
        for e in rd.flatten() {
            if let Some(name) = e.file_name().to_str() {
                entries.push(name.to_string());
            }
        }
    }
    if entries.is_empty() {
        println!("No cached challenges found.");
    } else {
        entries.sort();
        println!("Cached repositories:");
        for name in entries {
            println!("  {}", name);
        }
    }
}

fn count_cache(dir: &std::path::Path) -> (u64, u64) {
    let mut count: u64 = 0;
    let mut size: u64 = 0;
    if let Ok(rd) = std::fs::read_dir(dir) {
        for e in rd.flatten() {
            count += 1;
            if let Ok(meta) = e.metadata() {
                if meta.is_file() {
                    size += meta.len();
                } else if meta.is_dir() {
                    size += dir_size(&e.path());
                }
            }
        }
    }
    (count, size)
}

fn dir_size(p: &std::path::Path) -> u64 {
    let mut total = 0u64;
    if let Ok(rd) = std::fs::read_dir(p) {
        for e in rd.flatten() {
            if let Ok(meta) = e.metadata() {
                if meta.is_file() {
                    total += meta.len();
                } else if meta.is_dir() {
                    total += dir_size(&e.path());
                }
            }
        }
    }
    total
}
