use std::path::PathBuf;

use crate::error_log;
use crate::tui;

fn repo_dir() -> PathBuf {
    if let Some(home) = std::env::var_os("HOME") {
        let mut p = PathBuf::from(home);
        p.push(".gittype");
        p.push("repos");
        p
    } else {
        PathBuf::from(".gittype-repos")
    }
}

pub fn list(argv: &[String]) {
    let dir = repo_dir();
    if !dir.exists() {
        println!("No cached repositories directory found.");
        return;
    }
    // Otherwise attempt to initialize the TUI for interactive listing, which
    // matches the original tool's behavior and fails without a TTY.
    match tui::launch_tui() {
        Ok(()) => {}
        Err(e) => error_log::report_error(&e, argv),
    }
}

pub fn clear() {
    let dir = repo_dir();
    if dir.exists() {
        let _ = std::fs::remove_dir_all(&dir);
    }
    println!("Repositories cleared successfully.");
}
