use std::fs::{self, OpenOptions};
use std::io::Write;
use std::path::PathBuf;

use crate::time_util::now_utc;
use crate::tui::TerminalError;

pub fn report_error(e: &TerminalError, argv: &[String]) {
    let (y, mo, d, h, mi, s) = now_utc();
    let ts_name = format!("{:04}{:02}{:02}_{:02}{:02}{:02}", y, mo, d, h, mi, s);
    let ts_text = format!("{:04}-{:02}-{:02} {:02}:{:02}:{:02} UTC", y, mo, d, h, mi, s);
    let message = e.message();

    let error_type = "gittype::domain::error::GitTypeError";

    let body = build_error_body(
        &ts_text,
        error_type,
        &message,
        argv,
    );

    // Write gittype_error_YYYYMMDD_HHMMSS.log in cwd.
    let log_name = format!("gittype_error_{}.log", ts_name);
    let _ = fs::write(&log_name, &body);

    // Also write to $HOME/.gittype/logs/gittype_YYYYMMDD_HHMMSS.log
    if let Some(logs_dir) = home_logs_dir() {
        let _ = fs::create_dir_all(&logs_dir);
        let path = logs_dir.join(format!("gittype_{}.log", ts_name));
        let log_line_intro = format!(
            "{} [INFO] gittype::infrastructure::logging - GitType logging initialized, logs saved to: {}\n",
            ts_text,
            logs_dir.display()
        );
        let log_line_err = format!(
            "{} [ERROR] gittype::infrastructure::logging - APPLICATION ERROR:\n{}",
            ts_text, body
        );
        if let Ok(mut f) = OpenOptions::new().create(true).append(true).open(&path) {
            let _ = f.write_all(log_line_intro.as_bytes());
            let _ = f.write_all(log_line_err.as_bytes());
        }
    }

    eprintln!("💾 Error details written to: {}", log_name);
    eprintln!("Error: {}", message);
}

pub fn report_validation_error(message: &str, argv: &[String]) {
    let (y, mo, d, h, mi, s) = now_utc();
    let ts_name = format!("{:04}{:02}{:02}_{:02}{:02}{:02}", y, mo, d, h, mi, s);
    let ts_text = format!("{:04}-{:02}-{:02} {:02}:{:02}:{:02} UTC", y, mo, d, h, mi, s);
    let error_type = "gittype::domain::error::GitTypeError";
    let body = build_error_body(&ts_text, error_type, message, argv);

    let log_name = format!("gittype_error_{}.log", ts_name);
    let _ = fs::write(&log_name, &body);

    if let Some(logs_dir) = home_logs_dir() {
        let _ = fs::create_dir_all(&logs_dir);
        let path = logs_dir.join(format!("gittype_{}.log", ts_name));
        let line = format!(
            "{} [ERROR] gittype::infrastructure::logging - APPLICATION ERROR:\n{}",
            ts_text, body
        );
        if let Ok(mut f) = OpenOptions::new().create(true).append(true).open(&path) {
            let _ = f.write_all(line.as_bytes());
        }
    }

    eprintln!("💾 Error details written to: {}", log_name);
    eprintln!("Error: {}", message);
}

fn build_error_body(ts: &str, err_type: &str, msg: &str, argv: &[String]) -> String {
    let exe = std::env::current_exe()
        .ok()
        .and_then(|p| p.to_str().map(|s| s.to_string()))
        .unwrap_or_else(|| argv.first().cloned().unwrap_or_default());
    let cwd = std::env::current_dir()
        .ok()
        .and_then(|p| p.to_str().map(|s| s.to_string()))
        .unwrap_or_default();
    let args_joined: Vec<String> = argv.iter().map(|s| format!("{:?}", s)).collect();

    let mut body = String::new();
    body.push_str(&format!("ERROR OCCURRED AT: {}\n", ts));
    body.push_str(&format!("ERROR TYPE: {:?}\n", err_type));
    body.push_str(&format!("ERROR MESSAGE: {}\n", msg));
    body.push_str(&format!("EXECUTABLE: {:?}\n", exe));
    body.push_str(&format!("WORKING_DIR: {:?}\n", cwd));
    body.push_str(&format!("COMMAND_ARGS: [{}]\n", args_joined.join(", ")));
    body.push_str(&format!("OS: {}\n", std::env::consts::OS));
    body.push_str(&format!("ARCH: {}\n", std::env::consts::ARCH));
    body.push('\n');
    body
}

fn home_logs_dir() -> Option<PathBuf> {
    let home = std::env::var_os("HOME")?;
    let mut p = PathBuf::from(home);
    p.push(".gittype");
    p.push("logs");
    Some(p)
}
