pub const SUPPORTED_LANGS: &[&str] = &[
    "rust", "rs", "typescript", "ts", "javascript", "js",
    "python", "py", "ruby", "rb", "go", "swift",
    "kotlin", "kt", "java", "php", "csharp", "cs",
    "c#", "c", "cpp", "c++", "haskell", "hs",
    "dart", "scala", "sc", "zig", "clojure", "clj",
    "cljs",
];

// Languages accepted by the `trending` subcommand argument validator.
// Note: this list intentionally omits "Zig" even though the help text for
// `trending` advertises Zig. This mirrors the quirk in the upstream binary.
pub const TRENDING_VALIDATION_LANGUAGES: &[&str] = &[
    "C", "C#", "C++", "Dart", "Go", "Haskell", "Java", "JavaScript",
    "Kotlin", "PHP", "Python", "Ruby", "Rust", "Scala", "Swift",
    "TypeScript",
];

// Languages displayed in the `trending` subcommand help text.
pub const TRENDING_HELP_LANGUAGES: &[&str] = &[
    "C", "C#", "C++", "Dart", "Go", "Haskell", "Java", "JavaScript",
    "Kotlin", "PHP", "Python", "Ruby", "Rust", "Scala", "Swift",
    "TypeScript", "Zig",
];

pub fn validate_langs(s: &str) -> Result<(), String> {
    let mut unsupported: Vec<String> = Vec::new();
    for raw in s.split(',') {
        let norm = raw.trim_start().trim_end_matches('\0').to_lowercase();
        if !SUPPORTED_LANGS.iter().any(|x| x.eq_ignore_ascii_case(&norm)) {
            unsupported.push(raw.to_string());
        }
    }
    if unsupported.is_empty() {
        return Ok(());
    }
    let mut out = String::new();
    out.push_str(&format!("❌ Unsupported language(s): {}\n", unsupported.join(", ")));
    out.push_str("💡 Supported languages:\n");
    out.push_str("   rust, rs, typescript, ts, javascript, js\n");
    out.push_str("   python, py, ruby, rb, go, swift\n");
    out.push_str("   kotlin, kt, java, php, csharp, cs\n");
    out.push_str("   c#, c, cpp, c++, haskell, hs\n");
    out.push_str("   dart, scala, sc, zig, clojure, clj\n");
    out.push_str("   cljs\n");
    Err(out)
}

pub fn is_trending_language(s: &str) -> bool {
    TRENDING_VALIDATION_LANGUAGES.iter().any(|x| *x == s)
}
